.equ EVT_GET_HL, 0x1E00001	; Returns *(XHL)
.equ EVT_GET_IZ, 0x1E00002	; Returns *(XIZ)
.equ EVT_GET_CONFIG, 0x1E00003	; Returns *(XHL+0x0C)

