	.byte 0xf1, 0x42, 0x01, 0x00, 0x0f	; LD (MAMR0), 00fh
	.byte 0xf1, 0x46, 0x01, 0x00, 0x3f	; LD (MAMR1), 03fh
	.byte 0xf1, 0x4a, 0x01, 0x00, 0x7f	; LD (MAMR2), 07fh
	.byte 0xf1, 0x4e, 0x01, 0x00, 0x1f	; LD (MAMR3), 01fh
	.byte 0xf1, 0x52, 0x01, 0x00, 0xff	; LD (MAMR4), 0ffh
	.byte 0xf1, 0x56, 0x01, 0x00, 0xff	; LD (MAMR5), 0ffh

	; === Port 8 Setup (Chip Select) ===
	.byte 0x08, 0x20, 0x3b	; LD (P8), 03bh
	.byte 0x08, 0x23, 0x7f	; LD (P8FC), 07fh
	.byte 0x08, 0x22, 0x3f	; LD (P8CR), 03fh

