	.byte 0x31, 0x00, 0x20	; LD BC, 2000h
	.pause2:
	.byte 0xd9, 0x1c, 0xfd	; DJNZ BC, .pause2
	.byte 0xf1, 0x65, 0x01, 0x00, 0x71	; LD (DRAM1REF), 071h
	.byte 0xf1, 0x62, 0x01, 0x00, 0x8b	; LD (DRAM1CRL), 08bh
	.byte 0xf1, 0x63, 0x01, 0x00, 0x58	; LD (DRAM1CRH), 058h
	.byte 0xf1, 0x66, 0x01, 0xb4	; RES 4, (PMEMCR)

	; === Block Chip Select Low Configuration ===
	.byte 0xf1, 0x40, 0x01, 0x00, 0x11	; LD (B0CSL), 011h
	.byte 0xf1, 0x44, 0x01, 0x00, 0x33	; LD (B1CSL), 033h
	.byte 0xf1, 0x48, 0x01, 0x00, 0x11	; LD (B2CSL), 011h
	.byte 0xf1, 0x4c, 0x01, 0x00, 0x22	; LD (B3CSL), 022h
	.byte 0xf1, 0x50, 0x01, 0x00, 0x11	; LD (B4CSL), 011h
	.byte 0xf1, 0x54, 0x01, 0x00, 0x22	; LD (B5CSL), 022h

	; === Block Chip Select High Configuration ===
	.byte 0xf1, 0x41, 0x01, 0x00, 0x80	; LD (B0CSH), 080h
	.byte 0xf1, 0x45, 0x01, 0x00, 0x81	; LD (B1CSH), 081h
	.byte 0xf1, 0x49, 0x01, 0x00, 0xc2	; LD (B2CSH), 0c2h
	.byte 0xf1, 0x4d, 0x01, 0x00, 0x8a	; LD (B3CSH), 08ah
	.byte 0xf1, 0x51, 0x01, 0x00, 0x82	; LD (B4CSH), 082h
	.byte 0xf1, 0x55, 0x01, 0x00, 0x81	; LD (B5CSH), 081h

	; === Interrupt Mode Control ===
	.byte 0x08, 0xf6, 0x00	; LD (IIMC), 000h
	; End of shared boot hardware initialization (315 bytes)
	; ROM-specific code follows in each file
; --- end include: ../shared/boot_hw_init.asm ---
	; End of shared boot code (315 bytes)
	.byte 0x08, 0xd2, 0x29	; LD (SC0MOD), 029h
	.byte 0x08, 0xd1, 0x00	; LD (SC0CR), 000h
	.byte 0xc0, 0xd3, 0x3c, 0xcf	; AND (BR0CR), 0cfh
	.byte 0xc0, 0xd3, 0x3c, 0xf0	; AND (BR0CR), 0f0h


	.byte 0xf1, 0x30, 0x01, 0x00, 0xff	; LD (DAREG0), 0ffh
	.byte 0xf1, 0x31, 0x01, 0x00, 0xff	; LD (DAREG1), 0ffh
	.byte 0xf1, 0x32, 0x01, 0x00, 0x03	; LD (DADRV), 003h
	.byte 0x08, 0x3a, 0x20	; LD (PECR), 020h
	ld xsp, 0xC00
	.byte 0x1e, 0x1d, 0x06	; CALR Seems_to_copy_some_data_buffers


