	cp l, 0xFF
	.byte 0x6e, 0x19	; JR NZ, LABEL_EF054F

We_seem_to_be_running_boot_ROM_code:	; EF0536
	call 0xEF55A7
	.byte 0x0b, 0x08, 0x00	; PUSHW 0008h
	.byte 0x0b, 0x03, 0x00	; PUSHW 0003h
