; ===========================================================================
; User_didnt_request_flash_mem_update - Main Boot Sequence
; ===========================================================================
; This is the main boot path after power-on self-test and flash update check.
; Initializes Sub-CPU communication, transfers firmware payload, and verifies
; the transfer succeeded. On failure, displays the "ERROR in CPU data
; transmission" dialog (Screen Group 7).
;
; Boot flow:
;   1. Initialize DMA channels for inter-CPU communication
;   2. Send 192KB Sub-CPU firmware payload
;   3. Verify payload integrity (checksum validation)
;   4. Check error flag - if set, display error dialog
;   5. Continue to main UI initialization
;
; Error handling:
;   - If SubCPU_Payload_Verify returns non-zero in HL, boot with error state
;   - Error state (WA=2) displays error dialog via ScreenGroup_Dispatch
;   - Eventually Screen Group 7 "CPU data transmission" error is shown
;
; See also:
;   - SubCPU_Send_Payload - Payload transfer routine
;   - SubCPU_Payload_Verify - Checksum verification
;   - ErrorDialog_CPUTransmissionError - Error dialog widget
; ===========================================================================
User_didnt_request_flash_mem_update:	; EF05E8
	.byte 0xc1, 0x02, 0x04, 0x21	; LD A, (0402h)
	extz wa
	.byte 0x1e, 0x02, 0x02	; CALR LABEL_EF07F3
	.byte 0xf2, 0xca, 0xff, 0x00, 0x02, 0x00, 0x00	; LDW (0FFCAh:24), 0000h
	.byte 0xf0, 0x28, 0xb8	; SET 0, (PA)	; Release Sub-CPU from reset
	call 0xEF329E	; Initialize DMA for inter-CPU comm
	.byte 0x06, 0x00	; EI 000h
	.byte 0x1e, 0x86, 0x00	; CALR SubCPU_Send_Payload	; Transfer 192KB Sub-CPU firmware
	.byte 0x1e, 0x24, 0x03	; CALR SubCPU_Payload_Verify	; Verify payload checksum
	.byte 0xd8, 0xa8	; LD WA, 0
	call ScreenGroup_Dispatch	; Display initial boot screen (group 0)
	.byte 0x06, 0x00	; EI 000h
	call LABEL_FB76D8
	.byte 0x1e, 0x63, 0x03	; CALR SubCPU_Payload_GetErrorFlag	; Check if payload transfer failed
	.byte 0xdb, 0xd8	; CP HL, 0	; HL=0: success, HL!=0: error
	.byte 0x6e, 0x04	; JR NZ, Boot_PayloadError	; Branch if error occurred
	.byte 0xd8, 0xa9	; LD WA, 1	; Success: use screen group 1
	.byte 0x68, 0x02	; JR T, Boot_DisplayScreen

; Sub-CPU payload transfer or verification failed
Boot_PayloadError:	; EF061E
	.byte 0xd8, 0xaa	; LD WA, 2	; Error: use screen group 2

Boot_DisplayScreen:	; EF0620
	call ScreenGroup_Dispatch	; Display appropriate screen group
	.byte 0xf1, 0x00, 0x04, 0x00, 0x06	; LD (0400h), 006h
	.byte 0xd8, 0xab	; LD WA, 3
	call ScreenGroup_Dispatch
	.byte 0xf1, 0x00, 0x04, 0x00, 0x80	; LD (0400h), 080h
	.byte 0xf2, 0xd4, 0xff, 0x00, 0x02, 0x00, 0x00	; LDW (0FFD4h:24), 0000h
	.byte 0xc1, 0x02, 0x04, 0x21	; LD A, (0402h)
	extz wa
	.byte 0x1e, 0x5e, 0x01	; CALR LABEL_EF07A2
	.byte 0xd8, 0xac	; LD WA, 4
	call Show_ScreenGroup	; Show screen group 4 (may lead to error dialog)
	.byte 0x1e, 0x45, 0x01	; CALR LABEL_EF0792
	jp 0xEF1245


	.byte 0xc1, 0x02, 0x04, 0x27	; LD L, (0402h)
	ret


	.byte 0x08, 0xf0, 0x00	; LD (INTE0AD), 000h
	.byte 0x08, 0xe0, 0x00	; LD (INTE45), 000h
	.byte 0x08, 0xe1, 0x00	; LD (INTE67), 000h
	.byte 0x08, 0xe2, 0x00	; LD (INTE89), 000h
	.byte 0x08, 0xe3, 0x00	; LD (INTEAB), 000h
	.byte 0x08, 0xe4, 0x00	; LD (INTET01), 000h
	.byte 0x08, 0xe5, 0x00	; LD (INTET23), 000h
	.byte 0x08, 0xe6, 0x00	; LD (INTET45), 000h
	.byte 0x08, 0xe7, 0x00	; LD (INTET67), 000h
	.byte 0x08, 0xe8, 0x00	; LD (INTET89), 000h
	.byte 0x08, 0xe9, 0x00	; LD (INTETAB), 000h
	.byte 0x08, 0xea, 0x00	; LD (INTES0), 000h
	.byte 0x08, 0xeb, 0x00	; LD (INTES1), 000h
	.byte 0x08, 0xec, 0x00	; LD (INTETC01), 000h
	.byte 0x08, 0xed, 0x00	; LD (INTETC23), 000h
	.byte 0x08, 0xee, 0x00	; LD (INTETC45), 000h
	.byte 0x08, 0xef, 0x00	; LD (INTETC67), 000h
	ret

; ===========================================================================
; SubCPU_Send_Payload - Transfer 192KB Sub-CPU payload from Table Data ROM
; ===========================================================================
; Entry: None (reads from 0xFFFEEF to check if transfer should proceed)
; Exit:  XIZ restored, payload transferred to Sub-CPU RAM
; Notes: Sends the Sub-CPU firmware payload in multiple 64KB chunks:
;        - 0x830000-0x870000 (5 x 64KB) → Sub-CPU 0x050000-0x090000
;        - Additional data from Table Data ROM → Sub-CPU 0x00F000-0x02F000
;        - Final 256 bytes → Sub-CPU 0x000400 (entry point area)
;        Uses E1 bulk transfer protocol via InterCPU_E1_Bulk_Transfer
;        Includes 0x2000 and 0x100000 iteration delay loops for timing
;        Called during boot sequence after SubCPU_Init_DMA_Channels
; ===========================================================================
SubCPU_Send_Payload:
	push xiz
	.byte 0xc2, 0xef, 0xfe, 0xff, 0x3f, 0xff	; CP (0FFFEEFh), 0ffh
	.byte 0x7e, 0xf7, 0x00	; JRL NZ, LABEL_EF078B
	.byte 0xee, 0xa8	; LD XIZ, 0


	inc 1, xiz
	cp xiz, 0x2000
	.byte 0x67, 0xf6	; JR C, LABEL_EF0696
	ld xwa, 0x830000
	ld xbc, 0x10000
	ld xde, 0x50000
	call 0xEF3457
	ld xwa, 0x840000
	ld xbc, 0x10000
	ld xde, 0x60000
	call 0xEF3457
	ld xwa, 0x850000
	ld xbc, 0x10000
	ld xde, 0x70000
	call 0xEF3457
	ld xwa, 0x860000
	ld xbc, 0x10000
	ld xde, 0x80000
	call 0xEF3457
	ld xwa, 0x870000
	ld xbc, 0x10000
	ld xde, 0x90000
	call 0xEF3457
	.byte 0x46, 0x00, 0x00, 0x80, 0x00	; LD XIZ, TABLE_DATA_ROM__BASE_ADDR
	.byte 0xc2, 0xed, 0xfe, 0xff, 0x3f, 0xff	; CP (0FFFEEDh), 0ffh
	.byte 0x6e, 0x1e	; JR NZ, LABEL_EF072A
	ld xiz, 0x50000
	ld xwa, 0x3E0000
	ld xbc, 0x50000
	call LABEL_EF41E3
	cp hl, 0xFFFF
	.byte 0x6e, 0x05	; JR NZ, LABEL_EF072A
	.byte 0x46, 0x00, 0x00, 0x80, 0x00	; LD XIZ, TABLE_DATA_ROM__BASE_ADDR


	.byte 0xd3, 0xf9, 0x00, 0x01, 0x19, 0x04, 0x04	; LDW (0404h), (XIZ + 0100h)
	ld xwa, xiz
	add xwa, 0x100
	ld xbc, 0x10000
	ld xde, 0xF000
	call 0xEF3457
	ld xwa, xiz
	add xwa, 0x10100
	ld xbc, 0x10000
	ld xde, 0x1F000
	call 0xEF3457
	ld xwa, xiz
	add xwa, 0x20100
	.byte 0x31, 0x00, 0xff	; LD BC, 0ff00h
	ld xde, 0x2F000
	call 0xEF3457
	ld xwa, xiz
	.byte 0x31, 0x00, 0x01	; LD BC, 0100h
	ld xde, 0x400
	call 0xEF3457
	.byte 0xee, 0xa8	; LD XIZ, 0


	inc 1, xiz
	cp xiz, 0x100000
	.byte 0x67, 0xf6	; JR C, LABEL_EF0781


	pop xiz
	ret


	.byte 0xf1, 0x06, 0x04, 0xb7	; RES 7, (0406h)
	ret


	.byte 0xf1, 0x06, 0x04, 0xbf	; SET 7, (0406h)
	ret


	.byte 0xf1, 0x06, 0x04, 0x9f	; LDCF 7, (0406h)
	.byte 0xc9, 0x77	; SCC C, A
	.byte 0xc9, 0xd9	; CP A, 1
	.byte 0xdb, 0x76	; SCC Z, HL
	ret


	.byte 0xc9, 0xda	; CP A, 2
	.byte 0x6e, 0x22	; JR NZ, LABEL_EF07C8
	call 0xFFFEE5
	and l, 0xF
	extz hl
	.byte 0xf2, 0x00, 0x00, 0xe0, 0x31	; LDA XBC, LED_patterns_indicating_firmware_version
	.byte 0xc3, 0x07, 0xe4, 0xec, 0x23	; LD C, (XBC + HL)
	extz bc
	.byte 0xd8, 0xaf	; LD WA, 7
	call Set_LEDs
	push xiz
	call LABEL_FC3ECC
	pop xiz
	ret


	.byte 0xc9, 0xdb	; CP A, 3
	.byte 0xb0, 0xfe	; RET NZ
	.byte 0x30, 0xf0, 0x00	; LD WA, 00f0h
	call LABEL_F994BD
	ret


	ld xwa, 0x9FFFC4
	push xwa
	call LABEL_FF09A0
	inc 4, xsp
	ret


	.byte 0xd1, 0x04, 0x04, 0x23	; LD HL, (0404h)
	ret


	ld xwa, 0x87FFF5
	push xwa
	call LABEL_FF09A0
	inc 4, xsp
	ret


	.byte 0xd2, 0xca, 0xff, 0x00, 0x3f, 0xa5, 0x5a	; CPW (0FFCAh:24), 5aa5h
	.byte 0xb0, 0xf6	; RET Z
	.byte 0xc9, 0xd9	; CP A, 1
	.byte 0xb0, 0xfe	; RET NZ
	call LABEL_FC54B2
	.byte 0x06, 0x07	; EI 007h
	.byte 0x1e, 0x4d, 0xfe	; CALR LABEL_EF0656
	ld xbc, 0x400


	.byte 0xe8, 0xa8	; LD XWA, 0
	.byte 0xf5, 0xe6, 0x60	; LD (XBC+), XWA
	cp xbc, 0x100000
	.byte 0x67, 0xf3	; JR C, LABEL_EF080E
	ld xbc, 0x1E0000


	.byte 0xe8, 0xa8	; LD XWA, 0
	.byte 0xf5, 0xe6, 0x60	; LD (XBC+), XWA
	cp xbc, 0x200000
	.byte 0x67, 0xf3	; JR C, LABEL_EF0820
	.byte 0xf2, 0xca, 0xff, 0x00, 0x02, 0xa5, 0x5a	; LDW (0FFCAh:24), 5aa5h
	jp LABEL_EF050F

	.byte 0x0e


	.byte 0xc1, 0x6a, 0x8e, 0x27	; LD L, (8E6Ah)
	ret

; =============================================================================
; Shared boot routines (Detect_Region_Code, Get_Region_Code, handlers)
; Uses REGION_CODE_VAR and BOOT_ENTRY_POINT defined at top of file
; =============================================================================
; --- begin include: ../shared/boot_routines.asm ---
; =============================================================================
; boot_routines.asm - Common Boot Routines (Shared)
; =============================================================================
; This file contains boot routines that are structurally identical between
; the Main CPU ROM (maincpu) and Table Data ROM (table_data), differing only
; in RAM addresses and routine call targets.
;
; In maincpu: Located at 0xEF083E-0xEF08A0
; In table_data: Located at 0x9FB6D9-0x9FB738
;
; Required definitions before including this file:
;   REGION_CODE_VAR     - RAM address for region code storage
;                         (maincpu: 0x0408, table_data: 0x0C06)
;   BOOT_ENTRY_POINT    - Entry point for watchdog reset jump
;                         (maincpu: RESET_HANDLER, table_data: Boot_Init)
;   INDIRECT_CALL_HELPER - Address of indirect call routine
;                         (maincpu: 0xEF183D, table_data: 0xFFFA75)
;   INIT_HANDLER_TABLE  - Address of initialization handler table
;                         (maincpu: 0xFFFEF0, table_data: 0xFFFEF0)
;   INIT_FLAG_ADDR      - Address of init flag to check
;                         (maincpu: 0xFFFEEE, table_data: 0xFFFEEE)
;   CP_INIT_FLAG_ENCODING - Byte sequence for CP (INIT_FLAG_ADDR) comparison
;                         (maincpu uses 1-byte 0xFF, table_data uses 2-byte 0xFFFF)
;
; =============================================================================

; -----------------------------------------------------------------------------
; Detect_Region_Code - Detect region code from hardware switches
;
; Reads Port H bits 1 and 2 to determine the region:
;   PH.2=1, PH.1=1 -> Region 1
;   PH.2=1, PH.1=0 -> Region 2
;   PH.2=0, PH.1=1 -> Region 3
;   PH.2=0, PH.1=0 -> Region 4
;
; Entry: None
; Exit:  (REGION_CODE_VAR) = 1-4
; -----------------------------------------------------------------------------
Detect_Region_Code:
	.byte 0xf0, 0x44, 0xca	; BIT 2, (PH)
	.byte 0x66, 0x11	; JR Z, .check_bit1_only
	.byte 0xf0, 0x44, 0xc9	; BIT 1, (PH)
	.byte 0x66, 0x06	; JR Z, .mode2
	.byte 0xf1, 0x08, 0x04, 0x00, 0x01	; LD (REGION_CODE_VAR), 001h	; Region 1
	ret
	.mode2:
	.byte 0xf1, 0x08, 0x04, 0x00, 0x02	; LD (REGION_CODE_VAR), 002h	; Region 2
	ret
	.check_bit1_only:
	.byte 0xf0, 0x44, 0xc9	; BIT 1, (PH)
	.byte 0x66, 0x06	; JR Z, .mode4
	.byte 0xf1, 0x08, 0x04, 0x00, 0x03	; LD (REGION_CODE_VAR), 003h	; Region 3
	ret
	.mode4:
	.byte 0xf1, 0x08, 0x04, 0x00, 0x04	; LD (REGION_CODE_VAR), 004h	; Region 4
	ret

; -----------------------------------------------------------------------------
; Get_Region_Code - Get stored region code value
;
; Entry: None
; Exit:  L = region code (1-4)
; -----------------------------------------------------------------------------
Get_Region_Code:
	.byte 0xc1, 0x08, 0x04, 0x27	; LD L, (REGION_CODE_VAR)
	ret

; -----------------------------------------------------------------------------
; Empty_Handler - Empty interrupt handler
;
; Simply returns from interrupt without any processing.
; Used for unused interrupt vectors.
; -----------------------------------------------------------------------------
Empty_Handler:
	reti

; -----------------------------------------------------------------------------
; Watchdog_Reset_Handler - Watchdog interrupt handler
;
; Jumps back to boot entry point to restart initialization.
; This handles the case where the watchdog timer triggers during boot.
; -----------------------------------------------------------------------------
Watchdog_Reset_Handler:
	.byte 0x78, 0x58, 0xfb	; JRL T, BOOT_ENTRY_POINT
	reti	; Never reached

; End of shared boot routines
; --- end include: ../shared/boot_routines.asm ---

; =============================================================================
; Boot_CallInitHandlers - Call initialization handlers from table (Shared)
; Configuration for maincpu: byte comparison, local indirect call helper
; =============================================================================
.equ INIT_FLAG_COMPARE_WORD, 0	; maincpu uses byte comparison
.equ INDIRECT_CALL_HELPER, AudioMix_WriteChannelGroup	; indirect call helper in maincpu

; --- begin include: ../shared/boot_call_init_handlers.asm ---
; =============================================================================
; boot_call_init_handlers.asm - Init Handler Dispatch (Shared)
; =============================================================================
; This file contains the Boot_CallInitHandlers routine that is structurally
; identical between maincpu and table_data, with minor encoding differences.
;
; In maincpu: Located at 0xEF086F-0xEF08A3 (53 bytes)
; In table_data: Located at 0x9FB70A-0x9FB73F (54 bytes)
;
; Differences handled by conditional assembly:
;   1. Init flag comparison width:
;      - maincpu: CP (0xFFFEEE), 0xFF (byte comparison)
;      - table_data: CP (0xFFFEEE), 0xFFFF (word comparison)
;   2. Indirect call helper address:
;      - maincpu: 0xEF183D
;      - table_data: 0xFFFA75
;
; Required definitions before including this file:
;   INIT_FLAG_COMPARE_WORD  - Set to 1 for word comparison (table_data)
;                             Set to 0 for byte comparison (maincpu)
;   INDIRECT_CALL_HELPER    - Address of indirect call routine
;
; =============================================================================

; -----------------------------------------------------------------------------
; Boot_CallInitHandlers - Call initialization handlers from table
;
; If (0xFFFEEE) == 0xFF (maincpu) or 0xFFFF (table_data), calls up to 4 init
; handlers from a table at 0xFFFEF0. Each table entry is a 32-bit address.
;
; Table at 0xFFFEF0:
;   [0] = Handler 0 address (32-bit)
;   [1] = Handler 1 address (32-bit)
;   [2] = Handler 2 address (32-bit)
;   [3] = Handler 3 address (32-bit)
;
; Entry: None
; Exit: All handlers called if init flag was set
; -----------------------------------------------------------------------------
Boot_CallInitHandlers:
	.byte 0xd7, 0xfa, 0x04	; PUSH QIZ	; d7 fa 04

	; Compare init flag - encoding differs between ROMs
	; IF INIT_FLAG_COMPARE_WORD (evaluated to false for maincpu)
	; ELSE
	; maincpu: CP (0xFFFEEE), 0xFF (6 bytes)
	.byte 0xc2, 0xee, 0xfe, 0xff, 0x3f, 0xff
	; ENDIF

	.byte 0x6e, 0x26	; JR NZ, .done	; 6e xx (offset computed by assembler)

	; LD QIZH, 0
	.byte 0xc7, 0xfb, 0xa8

	.handler_loop:
	; LD A, QIZH
	.byte 0xc7, 0xfb, 0x89
	; EXTZ WA
	.byte 0xd8, 0x12
	; LD C, QIZH
	.byte 0xc7, 0xfb, 0x8b
	; EXTZ BC
	.byte 0xd9, 0x12
	; SLA 2, BC (multiply by 4 for 32-bit table entries)
	.byte 0xd9, 0xec, 0x02
	; LDA XDE, 0xFFFEF0 (init handler table)
	.byte 0xf2, 0xf0, 0xfe, 0xff, 0x32
	; LD XBC, (XDE+BC) - load handler address from table
	.byte 0xe3, 0x07, 0xe8, 0xe4, 0x21

	; Call indirect call helper (address differs between ROMs)
	call 0xEF183D

	; INC 1, QIZH
	.byte 0xc7, 0xfb, 0x61
	; CP QIZH, 4
	.byte 0xc7, 0xfb, 0xdc

	.byte 0x67, 0xdd	; JR C, .handler_loop	; 67 xx (offset computed by assembler)

	.done:
	.byte 0xd7, 0xfa, 0x05	; POP QIZ	; d7 fa 05
	ret	; 0e

; End of shared Boot_CallInitHandlers
; --- end include: ../shared/boot_call_init_handlers.asm ---

; Alias labels for backward compatibility with existing code
.equ LABEL_EF086F, Boot_CallInitHandlers

