; ===========================================================================
; SubCPU_Init_DMA_Channels - Initialize DMA channels for inter-CPU communication
; ===========================================================================
; Entry: None
; Exit:  DMA channels configured for Sub-CPU payload transfer
; Notes: Sets up MicroDMA channels 0 and 2 for inter-CPU latch communication
;        - DMA channel 2 destination = latch at 0x140000 (Main→Sub)
;        - DMA channel 0 source = latch at 0x140000 (Sub→Main)
;        - Configures interrupt priorities for DMA completion
;        - Clears transfer state variables at 0x05E0 and 0x05E2
;        Called during boot after Sub-CPU is released from reset
; ===========================================================================
SubCPU_Init_DMA_Channels:
	.byte 0xc0, 0xe5, 0x3c, 0xf8	; AND (INTET23), 0f8h
	.byte 0xf0, 0x80, 0xb2	; RES 2, (T8RUN)
	.byte 0xf0, 0xec, 0x31	; LDA XBC, INTETC01
	ld a, (xbc)
	and a, 0xF8
	or a, 0x5
	ld (xbc), a
	.byte 0xf0, 0xed, 0x31	; LDA XBC, INTETC23
	ld a, (xbc)
	and a, 0xF8
	or a, 0x5
	ld (xbc), a
	.byte 0xf0, 0xf0, 0x31	; LDA XBC, INTE0AD
	ld a, (xbc)
	and a, 0xF8
	.byte 0xc9, 0x31, 0x00	; SET 000h, A
	ld (xbc), a
	.byte 0x08, 0x8a, 0x07	; LD (TREG2), 007h
	.byte 0xf2, 0x00, 0x00, 0x14, 0x30	; LDA XWA, INTER_CPU_COMM_LATCHES
	.byte 0xe8, 0x2e, 0x28	; LDC_DMAD2_XWA
	.byte 0x21, 0x08	; LD_A 008h
	.byte 0xc9, 0x2e, 0x4a	; LDC_DMAM2_A
	.byte 0xf2, 0x00, 0x00, 0x14, 0x30	; LDA XWA, INTER_CPU_COMM_LATCHES
	.byte 0xe8, 0x2e, 0x00	; LDC_DMAS0_XWA
	.byte 0x21, 0x00	; LD_A 000h
	.byte 0xc9, 0x2e, 0x42	; LDC_DMAM0_A
	.byte 0xf1, 0xe0, 0x05, 0x00, 0x00	; LD (05E0h), 000h
	.byte 0xf1, 0xe2, 0x05, 0x00, 0x00	; LD (05E2h), 000h
	ret

sendCOMM:	; ef32f4
	dec 6, xsp
	.byte 0x2e	; PUSH IZ
	.byte 0xbf, 0x02, 0x62	; LD (XSP + 002h), XDE
	ld iz, bc
	.byte 0xbf, 0x06, 0x41	; LD (XSP + 006h), A
	.byte 0xd8, 0xaa	; LD WA, 2
	call 0xEF1FEE
	cp iz, 0x20
	.byte 0x63, 0x20	; JR ULE, LABEL_EF332B


	.byte 0x8f, 0x06, 0x21	; LD A, (XSP + 006h)
	extz wa
	.byte 0x31, 0x20, 0x00	; LD BC, 0020h
	.byte 0xaf, 0x02, 0x22	; LD XDE, (XSP + 002h)
	.byte 0x1e, 0x2c, 0x00	; CALR InterCPU_Send_Data_Block
	ld xwa, 0x20
	.byte 0xaf, 0x02, 0x88	; ADD (XSP + 002h), XWA
	sub iz, 0x20
	cp iz, 0x20
	.byte 0x6b, 0xe0	; JR UGT, LABEL_EF330B


	.byte 0x8f, 0x06, 0x21	; LD A, (XSP + 006h)
	extz wa
	.byte 0xc7, 0xf8, 0x8b	; LD C, IZL
	extz bc
	.byte 0xaf, 0x02, 0x22	; LD XDE, (XSP + 002h)
	.byte 0x1e, 0x0a, 0x00	; CALR InterCPU_Send_Data_Block
	.byte 0xd8, 0xaa	; LD WA, 2
	call 0xEF1F0F
	.byte 0x4e	; POP IZ
	inc 6, xsp
	ret

; ===========================================================================
; InterCPU_Send_Data_Block - Send a data packet to Sub-CPU
; ===========================================================================
; Entry: A = command/channel identifier (upper 3 bits)
;        C = byte count (1-32 bytes)
;        XDE = source data pointer
; Exit:  Data transferred to Sub-CPU
; Notes: Sends a variable-length data packet using encoded command byte:
;        - Command byte format: (A << 5) | (count - 1)
;        - Upper 3 bits = channel/command ID
;        - Lower 5 bits = byte count minus 1 (0-31 = 1-32 bytes)
;        Protocol:
;        1. Wait for SSTAT1 high (Sub-CPU ready)
;        2. Clear MSTAT0, set state to 1
;        3. Write encoded command byte to latch
;        4. Wait for SSTAT1 low (Sub-CPU acknowledged)
;        5. Set MSTAT0, send data via DMA
;        Timeout: 60000 iterations (0xEA60)
;        Called by sendCOMM for chunked audio data transfers
; ===========================================================================
InterCPU_Send_Data_Block:
	.byte 0xcb, 0xd8	; CP C, 0
	.byte 0xb0, 0xf6	; RET Z
	.byte 0xdc, 0xa8	; LD IX, 0


	.byte 0xf0, 0x68, 0xcb	; BIT 3, (PZ)	; SSTAT1 - test if Sub CPU is ready
	.byte 0x66, 0x41	; JR Z, LABEL_EF3391
	.byte 0xf0, 0x68, 0xb0	; RES 0, (PZ)	; MSTAT0 - clear to initiate handshake with Sub CPU
	.byte 0xf1, 0xe0, 0x05, 0x00, 0x01	; LD (05E0h), 001h
	ld l, c
	dec 1, l
	.byte 0xc9, 0xee, 0x05	; SLL 5, A
	or a, l
	.byte 0xf2, 0x00, 0x00, 0x14, 0x41	; LD (INTER_CPU_COMM_LATCHES), A
	.byte 0xdc, 0xa8	; LD IX, 0


	.byte 0xf0, 0x68, 0xcb	; BIT 3, (PZ)	; SSTAT1 - wait for Sub CPU to acknowledge (goes low)
	.byte 0x6e, 0x2f	; JR NZ, LABEL_EF339C
	.byte 0xf0, 0x68, 0xb8	; SET 0, (PZ)	; MSTAT0 - set to signal DMA data transfer starting
	.byte 0xf1, 0xda, 0x05, 0x62	; LD (05DAh), XDE
	extz bc
	.byte 0xf1, 0xde, 0x05, 0x51	; LD (05DEh), BC
	.byte 0x1e, 0x9e, 0x00	; CALR Audio_DMA_Transfer
	.byte 0xf1, 0xe0, 0x05, 0x00, 0x00	; LD (05E0h), 000h
	.byte 0xc1, 0xe0, 0x05, 0x3f, 0x00	; CP (05E0h), 000h
	.byte 0xb0, 0xf6	; RET Z


	.byte 0xc1, 0xe0, 0x05, 0x3f, 0x00	; CP (05E0h), 000h
	.byte 0x6e, 0xf9	; JR NZ, LABEL_EF3389
	ret


	ld hl, ix
	inc 1, ix
	cp hl, 0xEA60
	.byte 0x63, 0xb0	; JR ULE, LABEL_EF334B
	ret


	ld wa, ix
	inc 1, ix
	cp wa, 0xEA60
	.byte 0x63, 0xc2	; JR ULE, LABEL_EF3368
	.byte 0xf0, 0x68, 0xb8	; SET 0, (PZ)	; MSTAT0 - timeout recovery: force ready state
	ret

; ===========================================================================
; InterCPU_E2_Send - Send E2 extended transfer command
; ===========================================================================
; Entry: XWA = first parameter (4 bytes)
;        XDE = second parameter (4 bytes)
;        BC = third parameter (2 bytes)
; Exit:  10-byte header transferred to Sub-CPU
; Notes: Implements E2 command for extended transfers:
;        - Sends 10-byte header containing three parameters
;        - Used for complex audio operations requiring more metadata
;        Protocol similar to E1 but with larger header
;        Sets bit 7 of 0x0620 on completion
;        Timeout: 60000 iterations (0xEA60)
; ===========================================================================
InterCPU_E2_Send:
	.byte 0xdc, 0xa8	; LD IX, 0
	.byte 0xc1, 0xe0, 0x05, 0x3f, 0x00	; CP (05E0h), 000h
	.byte 0x66, 0x11	; JR Z, LABEL_EF33C4


	ld hl, ix
	inc 1, ix
	cp hl, 0xEA60
	.byte 0xb0, 0xfb	; RET UGT
	.byte 0xc1, 0xe0, 0x05, 0x3f, 0x00	; CP (05E0h), 000h
	.byte 0x6e, 0xef	; JR NZ, LABEL_EF33B3


	.byte 0xf0, 0x68, 0xb0	; RES 0, (PZ)	; MSTAT0 - clear to initiate E2 command handshake
	.byte 0xf1, 0xe0, 0x05, 0x00, 0x01	; LD (05E0h), 001h
	.byte 0xf2, 0x00, 0x00, 0x14, 0x00, 0xe2	; LD (INTER_CPU_COMM_LATCHES), 0e2h
	.byte 0xdc, 0xa8	; LD IX, 0


	.byte 0xf0, 0x68, 0xcb	; BIT 3, (PZ)	; SSTAT1 - wait for Sub CPU to acknowledge (goes low)
	.byte 0x6e, 0x34	; JR NZ, LABEL_EF340D
	.byte 0xf0, 0x68, 0xb8	; SET 0, (PZ)	; MSTAT0 - set to signal E2 header data ready
	.byte 0xf1, 0xc6, 0x05, 0x33	; LDA XHL, 05C6h
	ld (xhl), xwa
	.byte 0xbb, 0x04, 0x62	; LD (XHL + 004h), XDE
	.byte 0xbb, 0x08, 0x51	; LD (XHL + 008h), BC
	.byte 0xf1, 0xda, 0x05, 0x63	; LD (05DAh), XHL
	.byte 0xf1, 0xde, 0x05, 0x02, 0x0a, 0x00	; LDW (05DEh), 000ah
	.byte 0x1e, 0x26, 0x00	; CALR Audio_DMA_Transfer
	.byte 0xf1, 0xe0, 0x05, 0x00, 0x00	; LD (05E0h), 000h
	.byte 0xf1, 0x20, 0x06, 0xbf	; SET 7, (0620h)
	.byte 0xc1, 0xe0, 0x05, 0x3f, 0x00	; CP (05E0h), 000h
	.byte 0xb0, 0xf6	; RET Z


	.byte 0xc1, 0xe0, 0x05, 0x3f, 0x00	; CP (05E0h), 000h
	.byte 0x6e, 0xf9	; JR NZ, LABEL_EF3405
	ret


	ld hl, ix
	inc 1, ix
	cp hl, 0xEA60
	.byte 0x63, 0xbd	; JR ULE, LABEL_EF33D4
	.byte 0xf0, 0x68, 0xb8	; SET 0, (PZ)	; MSTAT0 - timeout recovery: force ready state
	ret

; ===========================================================================
; Audio_DMA_Transfer - Core DMA transfer routine for inter-CPU communication
; ===========================================================================
; Entry: Data pointer at 0x05DA, byte count at 0x05DE
; Exit:  Data transferred to Sub-CPU via DMA
; Notes: Transfers audio command/data blocks to Sub-CPU
;        Uses DMA channel configuration set up by Audio_InitDMAChannels
;        Handles both small transfers and large block transfers
; ===========================================================================
Audio_DMA_Transfer:
	.byte 0xd1, 0xde, 0x05, 0x20	; LD WA, (05DEh)
	ld de, wa
	extz xde
	.byte 0xd8, 0xd8	; CP WA, 0
	.byte 0x6e, 0x05	; JR NZ, LABEL_EF342C
	ld xde, 0x10000


	.byte 0xeb, 0xa8	; LD XHL, 0
	cp xde, 0x0
	.byte 0xb0, 0xf3	; RET ULE


	.byte 0xe1, 0xda, 0x05, 0x20	; LD XWA, (05DAh)
	.byte 0xf5, 0xe0, 0x31	; LDA_XBC_XWA_plus__e0__
	.byte 0xf1, 0xda, 0x05, 0x60	; LD (05DAh), XWA
	ld a, (xbc)
	.byte 0xf2, 0x00, 0x00, 0x14, 0x41	; LD (INTER_CPU_COMM_LATCHES), A
	.byte 0x21, 0x00	; LD_A 000h


	inc 1, a
	.byte 0xc9, 0xdb	; CP A, 3
	.byte 0x67, 0xfa	; JR C, LABEL_EF344A
	inc 1, xhl
	cp xhl, xde
	.byte 0x67, 0xe0	; JR C, LABEL_EF3436
	ret

; ===========================================================================
; InterCPU_E1_Bulk_Transfer - E1 two-phase bulk transfer protocol
; ===========================================================================
; Entry: XWA = source address in Main-CPU memory space
;        XBC = byte count to transfer
;        XDE = destination address in Sub-CPU memory space
; Exit:  IZ restored, data transferred to Sub-CPU
; Notes: Implements the E1 command protocol for bulk data transfers:
;        Phase 1: Send 6-byte header (dest addr + byte count)
;        Phase 2: Send actual data payload
;        Protocol:
;        1. Wait for previous transfer complete (05E0h == 0)
;        2. Wait for SSTAT1 high (Sub-CPU ready)
;        3. Clear MSTAT0, set state to 2 (two-phase)
;        4. Write 0xE1 to latch
;        5. Wait for SSTAT1 low (Sub-CPU acknowledged)
;        6. Set MSTAT0, send 6-byte header via DMA
;        7. Wait for state transition, send data payload
;        Timeout: 60000 iterations (0xEA60) for each wait loop
;        Used by SubCPU_Send_Payload for firmware payload transfer
; ===========================================================================
InterCPU_E1_Bulk_Transfer:
	.byte 0x2e	; PUSH IZ
	.byte 0xde, 0xa8	; LD IZ, 0
	.byte 0xc1, 0xe0, 0x05, 0x3f, 0x00	; CP (05E0h), 000h
	.byte 0x66, 0x12	; JR Z, LABEL_EF3473


	ld hl, iz
	inc 1, iz
	cp hl, 0xEA60
	.byte 0x7b, 0xb7, 0x00	; JRL UGT, LABEL_EF3523
	.byte 0xc1, 0xe0, 0x05, 0x3f, 0x00	; CP (05E0h), 000h
	.byte 0x6e, 0xee	; JR NZ, LABEL_EF3461


	.byte 0xde, 0xa8	; LD IZ, 0


	.byte 0xf0, 0x68, 0xcb	; BIT 3, (PZ)	; SSTAT1 - test if Sub CPU is ready for E1 transfer
	.byte 0x76, 0x8d, 0x00	; JRL Z, LABEL_EF3508
	.byte 0xf0, 0x68, 0xb0	; RES 0, (PZ)	; MSTAT0 - clear to initiate E1 bulk transfer
	.byte 0xf1, 0xe0, 0x05, 0x00, 0x02	; LD (05E0h), 002h
	.byte 0xf2, 0x00, 0x00, 0x14, 0x00, 0xe1	; LD (INTER_CPU_COMM_LATCHES), 0e1h
	.byte 0xde, 0xa8	; LD IZ, 0


	.byte 0xf0, 0x68, 0xcb	; BIT 3, (PZ)	; SSTAT1 - wait for Sub CPU to acknowledge E1 (goes low)
	.byte 0x7e, 0x84, 0x00	; JRL NZ, LABEL_EF3515
	.byte 0xf0, 0x68, 0xb8	; SET 0, (PZ)	; MSTAT0 - set to signal 6-byte header data ready
	.byte 0xf1, 0x08, 0x06, 0x33	; LDA XHL, 0608h
	ld (xhl), xwa
	.byte 0xf1, 0xd0, 0x05, 0x30	; LDA XWA, 05D0h
	ld (xwa), xde
	.byte 0xbb, 0x04, 0x51	; LD (XHL + 004h), BC
	.byte 0xb8, 0x04, 0x51	; LD (XWA + 004h), BC
	.byte 0xf1, 0xda, 0x05, 0x60	; LD (05DAh), XWA
	.byte 0xf1, 0xde, 0x05, 0x02, 0x06, 0x00	; LDW (05DEh), 0006h
	.byte 0x1e, 0x68, 0xff	; CALR Audio_DMA_Transfer
	.byte 0xf1, 0xe0, 0x05, 0x00, 0x01	; LD (05E0h), 001h
	.byte 0xc1, 0xe0, 0x05, 0x3f, 0x01	; CP (05E0h), 001h
	.byte 0x66, 0x07	; JR Z, LABEL_EF34C6


	.byte 0xc1, 0xe0, 0x05, 0x3f, 0x01	; CP (05E0h), 001h
	.byte 0x6e, 0xf9	; JR NZ, LABEL_EF34BF


	.byte 0xd8, 0xa8	; LD WA, 0


	inc 1, wa
	cp wa, 0xC8
	.byte 0x67, 0xf8	; JR C, LABEL_EF34C8
	.byte 0xf1, 0x08, 0x06, 0x31	; LDA XBC, 0608h
	ld xwa, (xbc)
	.byte 0xf1, 0xda, 0x05, 0x60	; LD (05DAh), XWA
	.byte 0x99, 0x04, 0x19, 0xde, 0x05	; LDW (05DEh), (XBC + 004h)
	.byte 0x1e, 0x39, 0xff	; CALR Audio_DMA_Transfer
	.byte 0xf1, 0xe0, 0x05, 0x00, 0x00	; LD (05E0h), 000h
	.byte 0xc1, 0xe0, 0x05, 0x3f, 0x00	; CP (05E0h), 000h
	.byte 0x66, 0x07	; JR Z, LABEL_EF34F5


	.byte 0xc1, 0xe0, 0x05, 0x3f, 0x00	; CP (05E0h), 000h
	.byte 0x6e, 0xf9	; JR NZ, LABEL_EF34EE


	.byte 0xde, 0xa8	; LD IZ, 0
	cp iz, 0xC8
	.byte 0x6f, 0x09	; JR NC, LABEL_EF3506


	nop
	inc 1, iz
	cp iz, 0xC8
	.byte 0x67, 0xf7	; JR C, LABEL_EF34FD


	.byte 0x68, 0x1b	; JR T, LABEL_EF3523


	ld hl, iz
	inc 1, iz
	cp hl, 0xEA60
	.byte 0x73, 0x62, 0xff	; JRL ULE, LABEL_EF3475
	.byte 0x68, 0x0e	; JR T, LABEL_EF3523


	ld hl, iz
	inc 1, iz
