	.byte 0xf1, 0x3e, 0x06, 0x60	; LD (063Eh), XWA
	.byte 0xe1, 0x42, 0x06, 0xf8	; CP (0642h), XWA
	.byte 0x7f, 0xdb, 0x00	; JRL NC, LABEL_EF4F60


	.byte 0x9f, 0x04, 0x7f	; SRLW (XSP + 004h)
	.byte 0x9f, 0x04, 0x20	; LD WA, (XSP + 004h)
