	extz xbc
	.byte 0xaf, 0x10, 0x81	; ADD XBC, (XSP + 010h)
	.byte 0xc7, 0xf8, 0x89	; LD A, IZL
	ld (xbc), a
	.byte 0x9f, 0x0a, 0x3c, 0xff, 0x0f	; ANDW (XSP + 00ah), 0fffh
	.byte 0x68, 0x7e	; JR T, LABEL_EF4F55


	.byte 0x1e, 0x2d, 0xfd	; CALR LABEL_EF4C07
	.byte 0xd7, 0xfa, 0x9b	; LD QIZ, HL
	.byte 0xd7, 0xfa, 0xcf, 0xff, 0xff	; CP QIZ, 0ffffh
	.byte 0x66, 0x7c	; JR Z, LABEL_EF4F60
	.byte 0x1e, 0x20, 0xfd	; CALR LABEL_EF4C07
	.byte 0xbf, 0x08, 0x53	; LD (XSP + 008h), HL
	.byte 0x9f, 0x08, 0x3f, 0xff, 0xff	; CPW (XSP + 008h), 0ffffh
	.byte 0x66, 0x6f	; JR Z, LABEL_EF4F60
	.byte 0x9f, 0x08, 0x21	; LD BC, (XSP + 008h)
	and bc, 0xF0
	.byte 0xd9, 0xee, 0x04	; SLL 4, BC
	.byte 0xd7, 0xfa, 0x88	; LD WA, QIZ
