FLASH_MEM_UPDATE:	; EF4F6F
	.byte 0xd7, 0xfa, 0x04	; PUSH QIZ
	call Check_for_Floppy_Disk_Change
	.byte 0xcf, 0xd8	; CP L, 0
	.byte 0x76, 0xc1, 0x00	; JRL Z, flash_update__not_today
	.byte 0x1e, 0xc3, 0xf2	; CALR LABEL_EF4241
	.byte 0x1e, 0x7d, 0xf3	; CALR Detect_Disk_Type
	.byte 0xc7, 0xfb, 0x9f	; LD QIZH, L
	call 0xEF0865
	.byte 0xcf, 0xdc	; CP L, 4
	.byte 0x66, 0x58	; JR Z, LABEL_EF4FE4
	call 0xEF3D0E
	cp xhl, 0xFFFFFFFF
	.byte 0x66, 0x4c	; JR Z, LABEL_EF4FE4
	.byte 0xc7, 0xfb, 0xde	; CP QIZH, 6	; Is it "HD-AEPRG DATA FILE"?
	.byte 0x66, 0x47	; JR Z, LABEL_EF4FE4	; yes, it is.
	.byte 0x0b, 0x08, 0x00	; PUSHW 0008h
	.byte 0x0b, 0x02, 0x00	; PUSHW 0002h
	.byte 0x40, 0x8e, 0x01, 0xe0, 0x00	; LD XWA, Bitmap_1bit_Flash_Memory_Update	; "Flash Memory Update"
	.byte 0x31, 0x30, 0x00	; LD BC, 0030h
	.byte 0x32, 0x50, 0x00	; LD DE, 0050h
	call Draw_FlashMemUpdate_message_bitmap
	.byte 0xc7, 0xfb, 0x89	; LD A, QIZH
	extz wa
	.byte 0x1e, 0x8b, 0xf7	; CALR Erase_and_Burn____when_disk_is_valid
	.byte 0x0b, 0x08, 0x00	; PUSHW 0008h
	.byte 0x0b, 0x01, 0x00	; PUSHW 0001h
	.byte 0x40, 0xc6, 0x08, 0xe0, 0x00	; LD XWA, Bitmap_1bit_Completed	; "Completed!"
	.byte 0x31, 0x30, 0x00	; LD BC, 0030h
	.byte 0x32, 0xa0, 0x00	; LD DE, 00a0h
	call Draw_FlashMemUpdate_message_bitmap
	.byte 0x0b, 0x08, 0x00	; PUSHW 0008h
	.byte 0x0b, 0x01, 0x00	; PUSHW 0001h
	.byte 0x40, 0x66, 0x12, 0xe0, 0x00	; LD XWA, Bitmap_1bit_Turn_On_AGAIN	; "Turn On AGAIN !!"
	.byte 0x31, 0x30, 0x00	; LD BC, 0030h
	.byte 0x32, 0xc8, 0x00	; LD DE, 00c8h
	call Draw_FlashMemUpdate_message_bitmap


	.byte 0xd8, 0xaa	; LD WA, 2
	call LABEL_EF379A
	cp hl, 0xFFFF
	.byte 0x66, 0x4c	; JR Z, flash_update__not_today
	.byte 0xc7, 0xfb, 0xde	; CP QIZH, 6	; Is it "HD-AEPRG DATA FILE"?
	.byte 0x6e, 0x47	; JR NZ, flash_update__not_today
	.byte 0x0b, 0x08, 0x00	; PUSHW 0008h
	.byte 0x0b, 0x02, 0x00	; PUSHW 0002h
	.byte 0x40, 0x8e, 0x01, 0xe0, 0x00	; LD XWA, Bitmap_1bit_Flash_Memory_Update	; "Flash Memory Update"
	.byte 0x31, 0x30, 0x00	; LD BC, 0030h
	.byte 0x32, 0x50, 0x00	; LD DE, 0050h
	call Draw_FlashMemUpdate_message_bitmap
	.byte 0xc7, 0xfb, 0x89	; LD A, QIZH
	extz wa
	.byte 0x1e, 0x33, 0xf7	; CALR Erase_and_Burn____when_disk_is_valid
	.byte 0x0b, 0x08, 0x00	; PUSHW 0008h
	.byte 0x0b, 0x01, 0x00	; PUSHW 0001h
	.byte 0x40, 0xc6, 0x08, 0xe0, 0x00	; LD XWA, Bitmap_1bit_Completed	; "Completed!"
	.byte 0x31, 0x30, 0x00	; LD BC, 0030h
	.byte 0x32, 0xa0, 0x00	; LD DE, 00a0h
	call Draw_FlashMemUpdate_message_bitmap
	.byte 0x0b, 0x08, 0x00	; PUSHW 0008h
	.byte 0x0b, 0x01, 0x00	; PUSHW 0001h
	.byte 0x40, 0x66, 0x12, 0xe0, 0x00	; LD XWA, Bitmap_1bit_Turn_On_AGAIN	; "Turn On AGAIN !!"
	.byte 0x31, 0x30, 0x00	; LD BC, 0030h
	.byte 0x32, 0xc8, 0x00	; LD DE, 00c8h
	call Draw_FlashMemUpdate_message_bitmap

flash_update__not_today:	; EF503C
	.byte 0xd7, 0xfa, 0x05	; POP QIZ
	ret

Draw_FlashMemUpdate_message_bitmap:	; EF5040
	dec 4, xsp
	.byte 0x2e	; PUSH IZ
	ld hl, bc
	.byte 0xbf, 0x02, 0x60	; LD (XSP + 002h), XWA
	ld iy, hl
	ld ix, de
	inc 1, ix
	.byte 0xde, 0xa8	; LD IZ, 0


	ld wa, iz
	extz xwa
	.byte 0xd8, 0x0a, 0x1c, 0x00	; DIVW_WA 001ch	; 28 bytes = 224 pixels de largura da imagem a ser desenhada
	.byte 0xd7, 0xe2, 0x88	; LD WA, QWA
	.byte 0xd8, 0xd8	; CP WA, 0
	.byte 0x6e, 0x04	; JR NZ, LABEL_EF5063
	ld iy, hl	; IY = coordanada X do canto esquerdo da imagem a ser desenhada
	dec 1, ix


	.byte 0xd7, 0xee, 0xa8	; LD QHL, 0


	ld de, iz
	extz xde
	.byte 0xaf, 0x02, 0x82	; ADD XDE, (XSP + 002h)
	.byte 0xf1, 0x6a, 0xe3, 0x30	; LDA XWA, 0E36Ah	; table of bit masks (equivalent to 1044h on boot "table_data" rom)
	.byte 0xd7, 0xee, 0x89	; LD BC, QHL
	extz xbc
	add xbc, xwa	; indexing bit masks with value of QHL
	ld a, (xbc)
	.byte 0x82, 0xc1	; AND A, (XDE)	; here XDE points at one of the bytes of the image we're drawing and we select the bit we need
	.byte 0xc7, 0xf2, 0x99	; LD QIXL, A
	ld de, ix
	extz xde
	.byte 0xf2, 0x00, 0x3c, 0x04, 0x31	; LDA XBC, OFFSCREEN_BUFFER_1	; aparentemente isso é um buffer offscreen

Set_XWA_to_320_times_XDE:
	ld xwa, xde
	.byte 0xe8, 0xee, 0x02	; SLL 2, XWA
	add xwa, xde
	.byte 0xe8, 0xee, 0x06	; SLL 6, XWA
	.byte 0xc7, 0xf2, 0xd8	; CP QIXL, 0
	.byte 0x66, 0x13	; JR Z, LABEL_EF50AA
	ld de, iy
	inc 1, iy
	extz xde
	add xwa, xde
	ld xde, xbc
	add xde, xwa
	.byte 0x8f, 0x0a, 0x21	; LD A, (XSP + 00ah)
	ld (xde), a
	.byte 0x68, 0x11	; JR T, LABEL_EF50BB


	ld de, iy
	inc 1, iy
	extz xde
	add xwa, xde	; XWA = 320*y + x
	ld xde, xbc
	add xde, xwa	; XDE = offscreen_buffer[320*y + x]
	.byte 0x8f, 0x0c, 0x21	; LD A, (XSP + 00ch)
	ld (xde), a


	.byte 0xd7, 0xee, 0x61	; INC 1, QHL
	.byte 0xd7, 0xee, 0xcf, 0x08, 0x00	; CP QHL, 0008h
	.byte 0x67, 0xa1	; JR C, LABEL_EF5066
	inc 1, iz
	cp iz, 0x268	; 28 bytes (224 pixels/line) * 22 lines = 0268h bytes
	.byte 0x67, 0x83	; JR C, LABEL_EF5050
	.byte 0xf2, 0x00, 0x00, 0x1a, 0x30	; LDA XWA, VIDEO_RAM_BASE
	.byte 0x32, 0x00, 0x96	; LD DE, 320 * 240 / 2	; 2 pixels per word
	call Copy_DE_words_from_XBC_to_XWA	; <-- "blit-screen"
	.byte 0x4e	; POP IZ
	inc 4, xsp
	.byte 0x0f, 0x04, 0x00	; RETD 0004h

;=============================================================================
; VRAM_FillRect - Fill a rectangular region in video RAM with a color
;
; Fills a 12-pixel tall rectangle in video RAM (0x1A0000) with the specified
; color value. Used for clearing or highlighting UI regions.
;
; Input:
;   BC = Y start coordinate (row)
;   WA = X start coordinate (column)
;   E  = Color/pattern value (8-bit, duplicated to 16-bit)
;
; Output:
;   None (VRAM modified)
;
; Clobbers: XIZ, XHL, XWA, XDE, IX, IY
;=============================================================================
VRAM_FillRect:	; EF50DF
	dec 6, xsp
	push xiz
	.byte 0xbf, 0x06, 0x45	; LD (XSP + 006h), E	; Save color value
	.byte 0xbf, 0x08, 0x50	; LD (XSP + 008h), WA	; Save X start
	ld ix, bc	; IX = Y start
	.byte 0xbf, 0x04, 0x51	; LD (XSP + 004h), BC
	.byte 0x9f, 0x04, 0x38, 0x0c, 0x00	; ADDW (XSP + 004h), 000ch	; End Y = start + 12
	.byte 0x9f, 0x04, 0xf4	; CP IX, (XSP + 004h)
	.byte 0x6f, 0x46	; JR NC, VRAM_FillRect_Done

VRAM_FillRect_RowLoop:
	.byte 0x9f, 0x08, 0x25	; LD IY, (XSP + 008h)	; IY = X start
	ld bc, iy
	inc 6, bc	; BC = X end (start + 6)
	cp iy, bc
	.byte 0x6f, 0x34	; JR NC, VRAM_FillRect_NextRow

VRAM_FillRect_ColLoop:
	ld de, iy
	extz xde
	ld wa, ix
	extz xwa
	ld xhl, xwa
	.byte 0xeb, 0xee, 0x02	; SLL 2, XHL
	add xhl, xwa
	.byte 0xeb, 0xee, 0x06	; SLL 6, XHL
	add xhl, xde
	.byte 0xeb, 0xef, 0x01	; SRL 1, XHL
	add xhl, xhl
	ld xiz, 0x1A0000
	add xiz, xhl
	.byte 0x8f, 0x06, 0x21	; LD A, (XSP + 006h)
	extz wa
	ld de, wa
	.byte 0xda, 0xee, 0x08	; SLL 8, DE
	or wa, de
	ld (xiz), wa
	inc 2, iy	; X += 2 (word increment)
	cp iy, bc
	.byte 0x67, 0xcc	; JR C, VRAM_FillRect_ColLoop

VRAM_FillRect_NextRow:
	inc 1, ix	; Y++
	.byte 0x9f, 0x04, 0xf4	; CP IX, (XSP + 004h)
	.byte 0x67, 0xba	; JR C, VRAM_FillRect_RowLoop

VRAM_FillRect_Done:
	pop xiz
	inc 6, xsp
	ret

; =============================================================================
; VGA Register I/O Routines - Shared with table_data ROM
; =============================================================================
; --- begin include: ../shared/vga_io.asm ---
; =============================================================================
; vga_io.asm - VGA Register I/O Routines (Shared)
; =============================================================================
; This file contains VGA register read/write routines that are byte-identical
; between the Main CPU ROM (maincpu) and Table Data ROM (table_data).
;
; In maincpu: Located at 0xEF5141-0xEF515F (30 bytes)
; In table_data: Located at 0x9FCDFC-0x9FCE1D (34 bytes)
;
; Requirements:
;   - Must define VGA_IO_BASE before including this file
;     (both ROMs use 0x170000)
;
; =============================================================================

; -----------------------------------------------------------------------------
; Write_VGA_Register - Write byte to VGA I/O port
;
; Entry: WA = port offset (e.g., 0x3C4 for sequencer address)
;        C = value to write
; Exit:  None
; Notes: Includes 256-iteration delay loop before write for bus timing
; -----------------------------------------------------------------------------
Write_VGA_Register:
	.byte 0xda, 0xa8	; LD DE, 0	; Initialize delay counter

	.delay:
	inc 1, de	; Increment counter
	cp de, 0x100	; Compare to 256
	.byte 0x67, 0xf8	; JR C, .delay	; Loop until DE >= 256

	extz xwa	; Zero-extend WA to XWA
	.byte 0x42, 0x00, 0x00, 0x17, 0x00	; LD XDE, VGA_IO_BASE	; Load VGA I/O base address
	add xde, xwa	; Add port offset
	ld (xde), c	; Write value to port
	ret

; -----------------------------------------------------------------------------
; Read_VGA_Register - Read byte from VGA I/O port
;
; Entry: WA = port offset
; Exit:  L = value read
; -----------------------------------------------------------------------------
Read_VGA_Register:
	extz xwa	; Zero-extend WA to XWA
	.byte 0x41, 0x00, 0x00, 0x17, 0x00	; LD XBC, VGA_IO_BASE	; Load VGA I/O base address
	add xbc, xwa	; Add port offset
	ld l, (xbc)	; Read value from port
	ret

; End of shared VGA I/O routines
; --- end include: ../shared/vga_io.asm ---

; =============================================================================
; VGA Initialization Code - Shared with table_data ROM
; Uses macros and code from ../shared/vga_init.asm
; =============================================================================
; --- begin include: ../shared/vga_init.asm ---
; =============================================================================
; vga_init.asm - VGA Hardware Initialization (Shared)
; =============================================================================
; This file contains VGA initialization code that is nearly byte-identical
; between the Main CPU ROM (maincpu) and Table Data ROM (table_data).
;
; In maincpu: Located at 0xEF5163-0xEF5AFD (2458 bytes)
; In table_data: Located at 0x9FCE1E-0x9FD7BB (2462 bytes)
;
; This code initializes:
;   - VGA sequencer extended registers
;   - VGA enable and misc output
;   - Standard sequencer registers
;   - Graphics controller registers
;   - CRTC timing registers
;   - Attribute controller (EGA palette)
;   - DAC palette (9 colors: black, white, RGB, CMY, dark blue)
;   - Calls back to extended init
;   - Sets up parameters for video buffer initialization
;
; Requirements:
;   - Must define Write_VGA_Register before including this file
;   - Must define Read_VGA_Register before including this file
;   - Must define VGA I/O port constants (VGA_ENABLE, VGA_SEQ_ADDR, etc.)
;   - Must define VIDEO_RAM_BASE and OFFSCREEN_BUFFER_1
;
; After including this file, each ROM must provide:
;   - CALL to memory fill routine (fills offscreen buffer)
;   - CALL to memory copy routine (blits to video RAM)
;   - Final VGA_SEQUENCER to turn screen on
; =============================================================================

; === VGA Macros ===
; These macros generate CALR instructions to Write_VGA_Register

.macro VGA_WRITE regnum,value
	.byte 0x30, 0xc4, 0x03	; LDW WA, regnum
	.byte 0x30, 0xc4, 0x03	; LDW BC, value
	.byte 0x30, 0xc4, 0x03	; CALR Write_VGA_Register
.endm

.macro VGA_SEQUENCER field,value
	.byte 0x30, 0xc4, 0x03, 0xd9, 0xae, 0x1e, 0xd6, 0xff	; VGA_WRITE VGA_SEQ_ADDR, field
	.byte 0x30, 0xc4, 0x03, 0xd9, 0xae, 0x1e, 0xd6, 0xff	; VGA_WRITE VGA_SEQ_DATA, value
.endm

.macro VGA_GFX_CONTROLLER field,value
	.byte 0x30, 0xc4, 0x03, 0xd9, 0xae, 0x1e, 0xd6, 0xff	; VGA_WRITE VGA_GC_ADDR, field
	.byte 0x30, 0xc4, 0x03, 0xd9, 0xae, 0x1e, 0xd6, 0xff	; VGA_WRITE VGA_GC_DATA, value
.endm

.macro VGA_COLOR_CRTC field,value
	.byte 0x30, 0xc4, 0x03, 0xd9, 0xae, 0x1e, 0xd6, 0xff	; VGA_WRITE VGA_CRTC_ADDR, field
	.byte 0x30, 0xc4, 0x03, 0xd9, 0xae, 0x1e, 0xd6, 0xff	; VGA_WRITE VGA_CRTC_DATA, value
.endm

.macro VGA_ATTRIBUTE field,value
	.byte 0x30, 0xc4, 0x03, 0xd9, 0xae, 0x1e, 0xd6, 0xff	; VGA_WRITE VGA_ATTR_ADDR, field
	.byte 0x30, 0xc4, 0x03, 0xd9, 0xae, 0x1e, 0xd6, 0xff	; VGA_WRITE VGA_ATTR_ADDR, value
.endm

; This macro is used at the end - uses JRL for a tail-call optimization
.macro RET_VGA_WRITE regnum,value
	.byte 0x30, 0xc4, 0x03	; LDW WA, regnum
	.byte 0x30, 0xc4, 0x03	; LDW BC, value
	.byte 0x30, 0xc4, 0x03	; JRL T, Write_VGA_Register
.endm

.macro RET_VGA_SEQUENCER field,value
	.byte 0x30, 0xc4, 0x03, 0xd9, 0xae, 0x1e, 0xd6, 0xff	; VGA_WRITE VGA_SEQ_ADDR, field
	.byte 0x30, 0xc4, 0x03, 0xd9, 0xae, 0x1e, 0xd6, 0xff	; RET_VGA_WRITE VGA_SEQ_DATA, value
.endm


