	.byte 0xf2, 0xf6, 0xd9, 0x03, 0x31	; LDA XBC, 03D9F6h	; Load table address
	.byte 0xe3, 0x07, 0xe4, 0xe0, 0x20	; LD XWA, (XBC + WA)	; Load entry from table
