	.byte 0xef, 0x60	; INC 8, XSP


	call 0xFA44D0
	ld xwa, xhl
	.byte 0xbf, 0x0e, 0x32	; LDA XDE, XSP + 00eh
	ld xbc, 0x1E0008C
	call 0xFA9660


	.byte 0xeb, 0xa8	; LD XHL, 0
	pop xiz
	.byte 0xbf, 0x12, 0x37	; LDA XSP, XSP + 012h
