	.byte 0xb0, 0xf3	; RET ULE
	.byte 0x27, 0x7f	; LD_L 07fh
	.byte 0x68, 0x0a	; JR T, LABEL_F1AA00


	.byte 0x89, 0x05, 0x27	; LD L, (XBC + 005h)
