	.byte 0xea, 0xad	; LD XDE, 5
	.byte 0x68, 0x1c	; JR T, Edit_Update

Edit_Default:
	ld xwa, xiz
	call 0xFA6266
	.byte 0xbb, 0x16, 0x31	; LDA XBC, XHL + 016h
	ld xwa, (xbc)
	cp xwa, 0xFFFFFFFF
	.byte 0x66, 0x0d	; JR Z, Edit_NoChange
	ld xwa, (xbc)
	ld xbc, 0x1C00002
	.byte 0xea, 0xa8	; LD XDE, 0

Edit_Update:
	call 0xFA9660

Edit_NoChange:
	.byte 0xeb, 0xa8	; LD XHL, 0

Edit_Return:
	pop xiz
	ret

EditControlProc:
	.byte 0xb0, 0x00, 0x00, 0xdb, 0xa8, 0x0e

