; FDC command dispatcher
; Reads command from (8A40h), dispatches to 12 handlers (0-0xB)
; Uses offset table at 0xEA98B2
FDC_COMMAND_DISPATCHER:	; F96DB1
	.byte 0xf1, 0x2a, 0x8a, 0x00, 0x00	; LD (8A2Ah), 000h
	.byte 0xd1, 0x40, 0x8a, 0x20	; LD WA, (8A40h)
	cp wa, 0xB
	.byte 0x6b, 0x24	; JR UGT, FDC_CheckDriveCount
	add wa, wa
	.byte 0xf2, 0xb2, 0x98, 0xea, 0x34	; LDA XIX, 0EA98B2h
	.byte 0xd3, 0x07, 0xf0, 0xe0, 0x20	; LD WA, (XIX + WA)
	.byte 0xf2, 0xd6, 0x6d, 0xf9, 0x34	; LDA XIX, FDC_CMD_HANDLER_BASE
	.byte 0xf3, 0x07, 0xf0, 0xe0, 0xd8	; JP T, XIX + WA
; FDC command handler base - entry point for command 0
FDC_CMD_HANDLER_BASE:	; F96DD6
	.byte 0x1e, 0xff, 0x00	; CALR FDC_SetupFormatParams
	.byte 0xc1, 0x24, 0x8a, 0x27	; LD L, (8A24h)
	ret

FDC_ReturnZero:
	.byte 0x27, 0x00	; LD_L 000h
	ret

FDC_ErrorInvalidDrive:
	.byte 0x1e, 0x26, 0x02	; CALR FDC_Validate_Drive_Head

FDC_CheckDriveCount:
	.byte 0xd1, 0x42, 0x8a, 0x20	; LD WA, (8A42h)
	.byte 0xf1, 0x2a, 0x8a, 0x41	; LD (8A2Ah), A
	.byte 0xc1, 0x2a, 0x8a, 0x3f, 0x01	; CP (8A2Ah), 001h
	.byte 0x63, 0x06	; JR ULE, FDC_ValidateCommand
	.byte 0x30, 0xfe, 0x00	; LD WA, 00feh
	.byte 0x78, 0xb4, 0x07	; JRL T, FDC_Set_Status

FDC_ValidateCommand:
	.byte 0xd1, 0x40, 0x8a, 0x20	; LD WA, (8A40h)
	.byte 0xd8, 0xdc	; CP WA, 4
	.byte 0x66, 0x21	; JR Z, FDC_ValidateTrack
	.byte 0xd8, 0xdb	; CP WA, 3
	.byte 0x66, 0x1d	; JR Z, FDC_ValidateTrack
	.byte 0xd8, 0xda	; CP WA, 2
	.byte 0x66, 0x19	; JR Z, FDC_ValidateTrack
	.byte 0xd8, 0xdd	; CP WA, 5
	.byte 0x66, 0x0d	; JR Z, FDC_Command5Handler
	cp wa, 0xB
	.byte 0x66, 0x04	; JR Z, FDC_NoOpReturn
	.byte 0xd8, 0xd9	; CP WA, 1
	.byte 0x6e, 0x0b	; JR NZ, FDC_ValidateTrack

FDC_NoOpReturn:
	.byte 0x27, 0x00	; LD_L 000h
	ret

FDC_Command5Handler:
	.byte 0x1e, 0xec, 0x01	; CALR FDC_Command5_Epilogue
	.byte 0xc1, 0x24, 0x8a, 0x27	; LD L, (8A24h)
	ret

FDC_ValidateTrack:
	.byte 0xd1, 0x46, 0x8a, 0x20	; LD WA, (8A46h)
	.byte 0xf1, 0x2b, 0x8a, 0x41	; LD (8A2Bh), A
	.byte 0xf1, 0x36, 0x8a, 0x41	; LD (8A36h), A
	extz wa
	.byte 0xd1, 0x08, 0x8b, 0xf0	; CP WA, (8B08h)
	.byte 0x67, 0x06	; JR C, FDC_HandleCmd2
	.byte 0x30, 0xfe, 0x00	; LD WA, 00feh
	.byte 0x78, 0x71, 0x07	; JRL T, FDC_Set_Status

