	.byte 0x6a, 0x59	; JR GT, LABEL_F97EBC
	.byte 0x1e, 0xad, 0xec	; CALR FDC_Read_Status
	.byte 0xcf, 0x33, 0x07	; BIT 7, L
	.byte 0x66, 0xee	; JR Z, LABEL_F97E59


	.byte 0x1e, 0xa5, 0xec	; CALR FDC_Read_Status
	.byte 0xcf, 0x33, 0x07	; BIT 7, L
	.byte 0x66, 0xf8	; JR Z, LABEL_F97E6B
	.byte 0x1e, 0x9d, 0xec	; CALR FDC_Read_Status
	.byte 0xcf, 0x33, 0x06	; BIT 6, L
	.byte 0x6e, 0x18	; JR NZ, LABEL_F97E93
	.byte 0x27, 0x00	; LD_L 0
	cp l, 0x80
	.byte 0x66, 0x0b	; JR Z, LABEL_F97E8D


	.byte 0x1e, 0x8e, 0xec	; CALR FDC_Read_Status
	and l, 0xF0
