; MIDI encoder routines moved to midi_encoder_routines.asm
; --- begin include: midi_encoder_routines.asm ---
; =============================================================================
; midi_encoder_routines.asm - MIDI Encoder Processing Routines
; =============================================================================
; This file contains the encoder dispatch and MIDI CC value processing
; routines for the KN5000 Main CPU.
;
; The encoder system works as follows:
; 1. Raw ADC values come from analog controllers (modwheel, volume, etc.)
; 2. CPanel_EncoderDispatch routes to encoder-specific handlers
; 3. Each handler uses lookup tables to convert raw -> MIDI CC values
; 4. Processed values are stored in MIDI_CC_*_VALUE variables
;
; Routines:
;   CPanel_EncoderDispatch    - Dispatch to encoder-specific handler
;   Encoder_ProcessModwheel   - Process modulation wheel (ID 2)
;   Encoder_ProcessVolume     - Process volume slider (ID 5)
;   Encoder_ClampScaleAndNormalize      - Clamp value to configured range
;   Encoder_ProcessBreath     - Process breath controller (ID 25)
;   Encoder_ProcessFoot       - Process foot controller (ID 26)
;   Encoder_ProcessExpression - Process expression (ID 27)
;   Encoder_PassthroughIdentity       - Simple passthrough (ID 31)
;   Encoder_ReturnDefaultConstant         - Return constant 1 (default/unused)
;   Encoder_ApplySystemModeSettings        - Select processing mode based on system state
;
; Required includes before this file:
;   - midi_encoder_constants.asm (or equivalent EQU definitions)
;
; =============================================================================

; CPanel_EncoderDispatch - Dispatch to encoder-specific handler
; Input: A = encoder data value, BC = encoder type/index
; Extracts encoder ID from bits 0-2 and 6-7, looks up handler in jump table
CPanel_EncoderDispatch:
	extz wa
	ld e, c
	and e, 0x7	; Extract bits 0-2 of encoder ID
	and c, 0xC0	; Extract bits 6-7
	.byte 0xcb, 0xef, 0x03	; SRL 3, C	; Shift to bits 3-4
	or c, e	; Combine to form 5-bit index
	extz bc
	.byte 0xd9, 0xec, 0x02	; SLA 002h, BC	; Multiply by 4 (jump table entry size)
	.byte 0xf2, 0xbc, 0xa0, 0xed, 0x32	; LDA XDE, ENCODER_HANDLER_TABLE
	exts xbc
	add xbc, xde	; XBC = table entry address
	ld xix, (xbc)	; Load handler address
	.byte 0xb4, 0xd8	; JP T, XIX	; Jump to handler

; ============================================================================
; Encoder Value Processing Handlers
; These routines process raw encoder inputs and convert them to MIDI CC values
; using lookup tables. Called via ENCODER_HANDLER_TABLE dispatch.
; ============================================================================

; Encoder_ProcessModwheel - Process modulation wheel input (Encoder ID 2)
; Input: A = raw encoder value
; Output: HL = processed MIDI CC value, or 0xFFFF if unchanged
Encoder_ProcessModwheel:
	.byte 0x33, 0xff, 0xff	; LD HL, 0FFFFh	; Default return = no change
	cpl a	; Invert input value
	ld c, a
	.byte 0xf1, 0xca, 0x8e, 0x43	; LD (ENCODER_RAW_MODWHEEL), C	; Store raw value
	.byte 0xc9, 0xef, 0x01	; SRL 001h, A	; Divide by 2
	extz wa
	.byte 0xf2, 0x3c, 0xa1, 0xed, 0x31	; LDA XBC, ENCODER_LUT_MODWHEEL	; Lookup table address
	.byte 0xc3, 0x07, 0xe4, 0xe0, 0x21	; LD A, (XBC + WA)	; Get processed value from table
	.byte 0xc1, 0xe4, 0x8e, 0x23	; LD C, (MIDI_CC_MODWHEEL_VALUE)	; Get current value
	.byte 0xcb, 0x30, 0x07	; RES 007h, C	; Clear change flag
	cp c, a	; Compare with new value
	.byte 0xb0, 0xf6	; RET Z	; Return if unchanged
	.byte 0xf1, 0xe4, 0x8e, 0x41	; LD (MIDI_CC_MODWHEEL_VALUE), A	; Store new value
	ld l, a
	extz hl	; Return value in HL
	ret

; Encoder_ProcessVolume - Process volume/expression slider (Encoder ID 5)
; Input: A = raw encoder value
; Output: HL = processed MIDI CC value, or 0xFFFF if unchanged
Encoder_ProcessVolume:
	.byte 0x2e	; PUSH IZ
	.byte 0x36, 0xff, 0xff	; LD IZ, 0FFFFh	; Default return = no change
	.byte 0xf1, 0xcc, 0x8e, 0x41	; LD (ENCODER_RAW_VOLUME), A	; Store raw value
	extz wa
	.byte 0xf2, 0xbc, 0xa1, 0xed, 0x31	; LDA XBC, ENCODER_LUT_VOLUME	; Lookup table address
	.byte 0xc3, 0x07, 0xe4, 0xe0, 0x21	; LD A, (XBC + WA)	; Get processed value
	.byte 0x1e, 0x15, 0x00	; CALR Encoder_ClampScaleAndNormalize	; Clamp to valid range
	ld a, l
	.byte 0xc1, 0xf4, 0x8e, 0xf1	; CP A, (MIDI_CC_VOLUME_VALUE)	; Compare with current
	.byte 0x66, 0x09	; JR Z, Encoder_ProcessVolume_NoChange
	.byte 0xf1, 0xf4, 0x8e, 0x41	; LD (MIDI_CC_VOLUME_VALUE), A	; Store new value
	.byte 0xc7, 0xf8, 0x99	; LD IZL, A
	extz iz	; IZ = new value

Encoder_ProcessVolume_NoChange:
	ld hl, iz	; Return value in HL
	.byte 0x4e	; POP IZ
	ret

; Encoder_ClampScaleAndNormalize - Clamp value L to minimum in ENCODER_RANGE_LIMIT
; Input: L = value to clamp, A = raw lookup value
; Output: HL = clamped and scaled value
Encoder_ClampScaleAndNormalize:
	ld l, a
	.byte 0xc1, 0xde, 0x8e, 0x23	; LD C, (ENCODER_RANGE_LIMIT)	; Get minimum limit
	cp l, c	; Compare with limit
	.byte 0x6f, 0x02	; JR NC, Encoder_PerformScaling	; Skip if >= limit
	ld l, c	; Clamp to minimum

Encoder_PerformScaling:
	sub l, c	; Subtract minimum
	.byte 0x26, 0x00	; LD_H 000h
	extz xhl
	.byte 0xeb, 0xee, 0x08	; SLL 008h, XHL	; Scale up (multiply by 256)
	ld xwa, xhl
	ld xbc, 0xEC	; Divisor
	call LABEL_FF0C18	; Division routine
	.byte 0xc1, 0xdc, 0x8e, 0x21	; LD A, (ENCODER_VOLUME_MODE)	; Get mode value
	extz wa
	add wa, wa	; Double for word table index
	.byte 0xf2, 0xbc, 0xa2, 0xed, 0x31	; LDA XBC, ENCODER_LUT_BREATH_INDEX	; Index table
	.byte 0xd3, 0x07, 0xe4, 0xe0, 0x21	; LD BC, (XBC + WA)	; Get index offset
	extz xbc
	ld xwa, xhl
	call LABEL_FF0A5C	; Processing routine
	ld xwa, xhl
	ld xbc, 0x14	; Constant
	call LABEL_FF0C18	; Division
	cp xhl, 0x7F	; Clamp to 127 max
	.byte 0xb0, 0xf3	; RET ULE	; Return if <= 127
	ld xhl, 0x7F	; Clamp to 127
	ret

; Encoder_ProcessBreath - Process breath controller input
; Input: A = raw encoder value
; Output: HL = processed MIDI CC value, or 0xFFFF if unchanged
Encoder_ProcessBreath:
	.byte 0x33, 0xff, 0xff	; LD HL, 0FFFFh	; Default return = no change
	cpl a	; Invert input
	.byte 0xf1, 0xd4, 0x8e, 0x41	; LD (ENCODER_RAW_BREATH), A	; Store raw value
	extz wa
	.byte 0xf2, 0xd2, 0xa2, 0xed, 0x31	; LDA XBC, ENCODER_LUT_BREATH_VALUE	; Lookup table
	.byte 0xc3, 0x07, 0xe4, 0xe0, 0x21	; LD A, (XBC + WA)	; Get processed value
	.byte 0xc1, 0x9b, 0x37, 0x23	; LD C, (0379Bh)	; Get system mode flags
	and c, 0xF	; Mask relevant bits
	.byte 0x6e, 0x07	; JR NZ, Encoder_ProcessBreath_WithModeAdjustment	; If mode active, process
	.byte 0xc1, 0x0b, 0x7f, 0x3f, 0x00	; CP (07F0Bh), 000h	; Check alternate condition
	.byte 0x66, 0x3e	; JR Z, Encoder_ProcessBreath_SimplePassthrough	; Simple processing if clear

Encoder_ProcessBreath_WithModeAdjustment:
	.byte 0xc1, 0xda, 0x8e, 0x23	; LD C, (ENCODER_BREATH_MODE)	; Get breath mode
	.byte 0xcb, 0xd8	; CP C, 0
	.byte 0xb0, 0xf6	; RET Z	; Return if disabled
	.byte 0xc9, 0xef, 0x01	; SRL 001h, A	; Divide by 2
	ld l, a
	extz hl
	dec 1, c	; Decrement mode for index
	extz bc
	add bc, bc	; Word index
	.byte 0xf2, 0xd2, 0xa3, 0xed, 0x30	; LDA XWA, ENCODER_LUT_BREATH_MULT	; Multiplier table
	.byte 0xd3, 0x07, 0xe0, 0xe4, 0x22	; LD DE, (XWA + BC)	; Get multiplier
	.byte 0xda, 0x43	; MUL XHL, DE	; Multiply
	.byte 0xf2, 0xea, 0xa3, 0xed, 0x30	; LDA XWA, ENCODER_LUT_BREATH_OFFSET	; Offset table
	.byte 0xd3, 0x07, 0xe0, 0xe4, 0x20	; LD WA, (XWA + BC)	; Get offset
	sub hl, wa	; Subtract offset
	add hl, 0x4080	; Add center offset
	.byte 0xdb, 0xef, 0x08	; SRL 008h, HL	; Divide by 256
	add hl, hl	; Double
	ld a, l
	.byte 0xf1, 0xe8, 0x8e, 0x41	; LD (MIDI_CC_BREATH_VALUE), A	; Store result
	.byte 0x68, 0x0e	; JR T, Encoder_ProcessBreath_Return

Encoder_ProcessBreath_SimplePassthrough:
	.byte 0xc1, 0xe8, 0x8e, 0xf9	; CP (MIDI_CC_BREATH_VALUE), A	; Compare with current
	.byte 0xb0, 0xf6	; RET Z	; Return if unchanged
	.byte 0xf1, 0xe8, 0x8e, 0x41	; LD (MIDI_CC_BREATH_VALUE), A	; Store new value
	ld l, a
	extz hl

Encoder_ProcessBreath_Return:
	ret

; Encoder_ProcessFoot - Process foot controller input
; Input: A = raw encoder value
; Output: HL = processed MIDI CC value, or 0xFFFF if unchanged
Encoder_ProcessFoot:
	.byte 0x33, 0xff, 0xff	; LD HL, 0FFFFh	; Default return = no change
	.byte 0xf1, 0xd6, 0x8e, 0x41	; LD (ENCODER_RAW_FOOT), A	; Store raw value
	.byte 0xc9, 0xef, 0x01	; SRL 001h, A	; Divide by 2
	extz wa
	.byte 0xf2, 0x02, 0xa4, 0xed, 0x31	; LDA XBC, ENCODER_LUT_FOOT	; Lookup table
	.byte 0xc3, 0x07, 0xe4, 0xe0, 0x21	; LD A, (XBC + WA)	; Get processed value
	.byte 0xc1, 0xea, 0x8e, 0x23	; LD C, (MIDI_CC_FOOT_VALUE)	; Get current value
	.byte 0xcb, 0x30, 0x07	; RES 007h, C	; Clear change flag
	cp c, a	; Compare
	.byte 0xb0, 0xf6	; RET Z	; Return if unchanged
	.byte 0xf1, 0xea, 0x8e, 0x41	; LD (MIDI_CC_FOOT_VALUE), A	; Store new value
	ld l, a
	extz hl	; Return value in HL
	ret

; Encoder_ProcessExpression - Process expression controller input
; Input: A = raw encoder value
; Output: HL = processed MIDI CC value (always returns value, no skip)
Encoder_ProcessExpression:
	cpl a	; Invert input
	ld c, a
	.byte 0xf1, 0xd8, 0x8e, 0x43	; LD (ENCODER_RAW_EXPRESSION), C	; Store raw value
	.byte 0xc9, 0xef, 0x01	; SRL 001h, A	; Divide by 2
	extz wa
	.byte 0xf2, 0x82, 0xa4, 0xed, 0x31	; LDA XBC, ENCODER_LUT_EXPRESSION	; Lookup table
	.byte 0xc3, 0x07, 0xe4, 0xe0, 0x21	; LD A, (XBC + WA)	; Get processed value
	.byte 0xf1, 0xe6, 0x8e, 0x41	; LD (MIDI_CC_EXPRESSION_VALUE), A	; Store value
	extz wa
	ld hl, wa	; Return value in HL
	ret

; Encoder_PassthroughIdentity - Simple passthrough: returns input value in HL
; Input: A = value
; Output: HL = value
Encoder_PassthroughIdentity:
	ld l, a
	extz hl
	ret

; Encoder_ReturnDefaultConstant - Returns constant 1
; Output: HL = 1
Encoder_ReturnDefaultConstant:
	.byte 0xdb, 0xa9	; LD HL, 1
	ret

; Encoder_ApplySystemModeSettings - Select processing mode based on system state
; Reads mode value from 0xC07D and configures encoder processing accordingly
Encoder_ApplySystemModeSettings:
	.byte 0xc1, 0x7d, 0xc0, 0x21	; LD A, (0C07Dh)	; Get mode selector
	.byte 0xc9, 0xde	; CP A, 6
	.byte 0x66, 0x32	; JR Z, Encoder_ConfigureRangeLimit	; Jump if mode 6
	.byte 0xc9, 0xdd	; CP A, 5
	.byte 0x66, 0x19	; JR Z, Encoder_ConfigureVolumeMode	; Jump if mode 5
	.byte 0xc9, 0xdc	; CP A, 4
	.byte 0xb0, 0xfe	; RET NZ	; Return if not mode 4
	; Mode 4: Configure breath mode
	.byte 0xc1, 0x7f, 0xc0, 0x21	; LD A, (0C07Fh)
	and a, 0xF	; Mask low nibble
	.byte 0xb0, 0xf6	; RET Z	; Return if zero
	.byte 0xc1, 0x7e, 0xc0, 0x21	; LD A, (0C07Eh)
	and a, 0xF	; Mask low nibble
	.byte 0xf1, 0xda, 0x8e, 0x41	; LD (ENCODER_BREATH_MODE), A	; Set breath mode
	ret

Encoder_ConfigureVolumeMode:
	.byte 0xc1, 0x7f, 0xc0, 0x21	; LD A, (0C07Fh)
	and a, 0xFF	; Full byte check
	.byte 0xb0, 0xf6	; RET Z	; Return if zero
	.byte 0xc1, 0x7e, 0xc0, 0x21	; LD A, (0C07Eh)
	and a, 0xFF	; Full byte
	.byte 0xf1, 0xdc, 0x8e, 0x41	; LD (ENCODER_VOLUME_MODE), A	; Set volume mode
	ret

Encoder_ConfigureRangeLimit:
	.byte 0xc1, 0x7f, 0xc0, 0x21	; LD A, (0C07Fh)
	.byte 0xc9, 0x30, 0x07	; RES 007h, A	; Clear bit 7
	.byte 0xc9, 0xd8	; CP A, 0
	.byte 0xb0, 0xf6	; RET Z	; Return if zero
	.byte 0xc1, 0x7e, 0xc0, 0x21	; LD A, (0C07Eh)
	.byte 0xc9, 0x30, 0x07	; RES 007h, A	; Clear bit 7
	.byte 0xf1, 0xde, 0x8e, 0x41	; LD (ENCODER_RANGE_LIMIT), A	; Set range limit
	ret

